const data = $input.first().json;
const userBooks = data?.data?.me?.[0]?.user_books ?? [];

if (userBooks.length === 0) {
  return [];
}

return userBooks.map(ub => {
  const book = ub.book;
  const title = book?.title ?? 'Unknown Title';
  const hcSlug = book?.slug ?? null;
  const authors = (book?.contributions ?? []).map(c => c.author?.name).filter(Boolean);
  const author = authors.join(', ') || null;
  const editions = book?.editions ?? [];
  const isbn13 = editions[0]?.isbn_13 ?? null;
  const isbn10 = editions[0]?.isbn_10 ?? null;
  const isbn = isbn13 || isbn10 || null;
  const coverUrl = editions[0]?.image?.url ?? book?.image?.url ?? null;
  const rating = ub.rating ?? null;
  const updatedAt = ub.updated_at;
  const finishedAt = ub.user_book_reads?.[0]?.finished_at ?? null;
  const journalDate = ub.reading_journals?.[0]?.action_at ?? null;
  const fallbackDate = finishedAt || journalDate || updatedAt;
  const seriesEntry = book?.book_series?.[0] ?? null;
  const seriesName = seriesEntry?.series?.name ?? null;
  const seriesPos = seriesEntry?.position ?? null;

  const statusId = ub.status_id;
  const isFinished = statusId === 3;
  const readStatus = isFinished ? 'finished' : 'reading';
  const summaryPrefix = isFinished ? 'Finished reading' : 'Currently reading';

  let summary = `${summaryPrefix}: ${title}`;
  if (author) summary += ` by ${author}`;

  const readOfProps = { name: [title] };
  if (author) readOfProps.author = [author];
  if (isbn) readOfProps.uid = [`isbn:${isbn}`];

  const props = {
    summary: [summary],
    'read-status': [readStatus],
    'read-of': [{ type: ['h-cite'], properties: readOfProps }],
    category: ['book'],
    visibility: ['public'],
    'post-status': ['published']
  };

  if (rating !== null) {
    const stars = Math.round(rating);
    props.summary[0] += ` ${'★'.repeat(stars)}${'☆'.repeat(5 - stars)} (${rating}/5)`;
  }
  if (coverUrl) props['hardcover-cover'] = [coverUrl];
  if (isFinished && fallbackDate) props['finished-at'] = [fallbackDate];
  if (seriesName) props['book-series'] = [seriesName];
  if (hcSlug) props['hardcover-slug'] = [hcSlug];
  if (seriesPos != null) props['book-series-position'] = [String(seriesPos)];

  const micropubBody = { type: ['h-entry'], properties: props };
  return { json: { micropubBody, updatedAt, title } };
});

// watermark comes from WP REST API (self-healing), no persistence needed
const now = new Date().toISOString();
return [{ json: { updated: true, lastChecked: now } }];
